171:      * Infers {@link StateInfo}s using the given {@link StateTypeStrategy}s. It assumes that input
172:      * arguments have been adapted before if necessary.
173:      */
174:     public static LinkedHashMap<String, StateInfo> inferStateInfos(
175:             CallContext callContext, LinkedHashMap<String, StateTypeStrategy> stateTypeStrategies) {
176:         return stateTypeStrategies.entrySet().stream()
177:                 .map(
178:                         e ->
179:                                 Map.entry(
180:                                         e.getKey(),
181:                                         inferStateInfo(callContext, e.getKey(), e.getValue())))
182:                 .collect(
183:                         Collectors.toMap(
184:                                 Map.Entry::getKey,
185:                                 Map.Entry::getValue,
186:                                 (x, y) -> y,
187:                                 LinkedHashMap::new));
188:     }
