190:     /** Generates a signature of the given {@link FunctionDefinition}. */
191:     public static String generateSignature(
192:             TypeInference typeInference, String name, FunctionDefinition definition) {
193:         final List<StaticArgument> staticArguments =
194:                 typeInference.getStaticArguments().orElse(null);
195:         if (staticArguments != null) {
196:             return formatStaticArguments(name, staticArguments);
