229:     /** Returns an exception for an unexpected error during type inference. */
230:     public static TableException createUnexpectedException(
231:             CallContext callContext, Throwable cause) {
232:         return new TableException(
233:                 String.format(
234:                         "Unexpected error in type inference logic of function '%s'. This is a bug.",
235:                         callContext.getName()),
236:                 cause);
237:     }
