281:     /**
282:      * Information what the outer world (i.e. an outer wrapping call) expects from the current
283:      * function call. This can be helpful for an {@link InputTypeStrategy}.
284:      *
285:      * @see CallContext#getOutputDataType()
286:      */
287:     @Internal
288:     public interface SurroundingInfo {
289: 
290:         static SurroundingInfo of(
291:                 String name,
292:                 FunctionDefinition functionDefinition,
293:                 TypeInference typeInference,
294:                 int argumentCount,
295:                 int innerCallPosition,
296:                 boolean isGroupedAggregation) {
297:             return typeFactory -> {
298:                 final boolean isValidCount =
299:                         validateArgumentCount(
300:                                 typeInference.getInputTypeStrategy().getArgumentCount(),
301:                                 argumentCount,
302:                                 false);
303:                 if (!isValidCount) {
304:                     return Optional.empty();
305:                 }
306:                 // for "takes_string(this_function(NULL))" simulate "takes_string(NULL)"
307:                 // for retrieving the output type of "this_function(NULL)"
308:                 final CallContext callContext =
309:                         new UnknownCallContext(
310:                                 typeFactory,
311:                                 name,
312:                                 functionDefinition,
313:                                 argumentCount,
314:                                 isGroupedAggregation);
315: 
316:                 // We might not be able to infer the input types at this moment, if the surrounding
317:                 // function does not provide an explicit input type strategy.
318:                 final CallContext adaptedContext =
319:                         adaptArguments(typeInference, callContext, null, false);
320:                 return typeInference
321:                         .getInputTypeStrategy()
322:                         .inferInputTypes(adaptedContext, false)
323:                         .map(dataTypes -> dataTypes.get(innerCallPosition));
324:             };
325:         }
326: 
327:         static SurroundingInfo of(DataType dataType) {
328:             return typeFactory -> Optional.of(dataType);
329:         }
330: 
331:         Optional<DataType> inferOutputType(DataTypeFactory typeFactory);
332:     }
