334:     /**
335:      * The result of a type inference run. It contains information about how arguments need to be
336:      * adapted in order to comply with the function's signature.
337:      *
338:      * <p>This includes casts that need to be inserted, reordering of arguments (*), or insertion of
339:      * default values (*) where (*) is future work.
340:      */
341:     @Internal
342:     public static final class Result {
343: 
344:         private final List<DataType> expectedArgumentTypes;
345: 
346:         private final LinkedHashMap<String, StateInfo> stateInfos;
347: 
348:         private final DataType outputDataType;
349: 
350:         public Result(
351:                 List<DataType> expectedArgumentTypes,
352:                 LinkedHashMap<String, StateInfo> stateInfos,
353:                 DataType outputDataType) {
354:             this.expectedArgumentTypes = expectedArgumentTypes;
355:             this.stateInfos = stateInfos;
356:             this.outputDataType = outputDataType;
357:         }
358: 
359:         public List<DataType> getExpectedArgumentTypes() {
360:             return expectedArgumentTypes;
361:         }
362: 
363:         public LinkedHashMap<String, StateInfo> getStateInfos() {
364:             return stateInfos;
365:         }
366: 
367:         public DataType getOutputDataType() {
368:             return outputDataType;
369:         }
370:     }
