99:      *
100:      * <p>This includes casts that need to be inserted, reordering of arguments (*), or insertion of
101:      * default values (*) where (*) is future work.
102:      */
103:     public static CallContext adaptArguments(
104:             TypeInference typeInference, CallContext callContext, @Nullable DataType outputType) {
105:         return adaptArguments(typeInference, callContext, outputType, true);
106:     }
107: 
108:     private static CallContext adaptArguments(
109:             TypeInference typeInference,
110:             CallContext callContext,
111:             @Nullable DataType outputType,
112:             boolean throwOnInferInputFailure) {
113:         final List<DataType> actualTypes = callContext.getArgumentDataTypes();
114: 
115:         typeInference
116:                 .getStaticArguments()
117:                 .ifPresent(
118:                         staticArgs -> {
119:                             if (actualTypes.size() != staticArgs.size()) {
120:                                 throw new ValidationException(
121:                                         String.format(
122:                                                 "Invalid number of arguments. %d arguments expected after argument expansion but %d passed.",
123:                                                 staticArgs.size(), actualTypes.size()));
124:                             }
125:                         });
126: 
127:         final AdaptedCallContext castCallContext =
128:                 inferInputTypes(typeInference, callContext, outputType, throwOnInferInputFailure);
129: 
130:         // final check if the call is valid after casting
131:         final List<DataType> expectedTypes = castCallContext.getArgumentDataTypes();
132:         for (int pos = 0; pos < actualTypes.size(); pos++) {
133:             final DataType expectedType = expectedTypes.get(pos);
134:             final DataType actualType = actualTypes.get(pos);
135:             if (!supportsImplicitCast(actualType.getLogicalType(), expectedType.getLogicalType())) {
136:                 if (!throwOnInferInputFailure) {
137:                     // abort the adaption, e.g. if a NULL is passed for a NOT NULL argument
138:                     return callContext;
139:                 }
140:                 throw new ValidationException(
141:                         String.format(
142:                                 "Invalid argument type at position %d. Data type %s expected but %s passed.",
143:                                 pos, expectedType, actualType));
144:             }
145:         }
146: 
147:         return castCallContext;
148:     }
