150:     /**
151:      * Infers an output type using the given {@link TypeStrategy}. It assumes that input arguments
152:      * have been adapted before if necessary.
153:      */
154:     public static DataType inferOutputType(
155:             CallContext callContext, TypeStrategy outputTypeStrategy) {
156:         final Optional<DataType> potentialOutputType = outputTypeStrategy.inferType(callContext);
157:         if (potentialOutputType.isEmpty()) {
158:             throw new ValidationException(
159:                     "Could not infer an output type for the given arguments.");
160:         }
161:         final DataType outputType = potentialOutputType.get();
162: 
163:         if (isUnknown(outputType)) {
164:             throw new ValidationException(
165:                     "Could not infer an output type for the given arguments. Untyped NULL received.");
166:         }
167:         return outputType;
168:     }
