372:     /** Result of running {@link StateTypeStrategy}. */
373:     @Internal
374:     public static final class StateInfo {
375: 
376:         private final DataType dataType;
377:         private final @Nullable Duration timeToLive;
378: 
379:         private StateInfo(DataType dataType, @Nullable Duration timeToLive) {
380:             this.dataType = dataType;
381:             this.timeToLive = timeToLive;
382:         }
383: 
384:         public DataType getDataType() {
385:             return dataType;
386:         }
