249:             TableConfig tableConfig = ShortcutUtils.unwrapContext(relOptCluster).getTableConfig();
250:             ZoneId zoneId = tableConfig.getLocalTimeZone();
251:             long timeTravelTimestamp =
252:                     TimestampData.fromEpochMillis(timestampString.getMillisSinceEpoch())
253:                             .toLocalDateTime()
254:                             .atZone(zoneId)
255:                             .toInstant()
256:                             .toEpochMilli();
