409:     /**
410:      * A special {@link SqlSelect} to capture the origin of a {@link SqlKind#EXPLICIT_TABLE} within
411:      * TVF operands.
412:      */
413:     private static class ExplicitTableSqlSelect extends SqlSelect {
414: 
415:         private final List<SqlIdentifier> descriptors;
416: 
417:         public ExplicitTableSqlSelect(SqlIdentifier table, List<SqlIdentifier> descriptors) {
418:             super(
419:                     SqlParserPos.ZERO,
420:                     null,
421:                     SqlNodeList.of(SqlIdentifier.star(SqlParserPos.ZERO)),
422:                     table,
423:                     null,
424:                     null,
425:                     null,
426:                     null,
427:                     null,
428:                     null,
429:                     null,
430:                     null);
431:             this.descriptors = descriptors;
432:         }
433:     }
