154:     protected void validateJoin(SqlJoin join, SqlValidatorScope scope) {
155:         // Due to the improper translation of lateral table left outer join in Calcite, we need to
156:         // temporarily forbid the common predicates until the problem is fixed (see FLINK-7865).
157:         if (join.getJoinType() == JoinType.LEFT
158:                 && SqlUtil.stripAs(join.getRight()).getKind() == SqlKind.COLLECTION_TABLE) {
159:             SqlNode right = SqlUtil.stripAs(join.getRight());
160:             if (right instanceof SqlBasicCall) {
161:                 SqlBasicCall call = (SqlBasicCall) right;
162:                 SqlNode operand0 = call.operand(0);
163:                 if (operand0 instanceof SqlBasicCall
164:                         && ((SqlBasicCall) operand0).getOperator()
165:                                 instanceof org.apache.calcite.sql.SqlWindowTableFunction) {
166:                     return;
167:                 }
168:             }
169:             final SqlNode condition = join.getCondition();
170:             if (condition != null
171:                     && (!SqlUtil.isLiteral(condition)
172:                             || ((SqlLiteral) condition).getValueAs(Boolean.class)
173:                                     != Boolean.TRUE)) {
174:                 throw new ValidationException(
175:                         String.format(
176:                                 "Left outer joins with a table function do not accept a predicate such as %s. "
177:                                         + "Only literal TRUE is accepted.",
178:                                 condition));
179:             }
180:         }
181:         super.validateJoin(join, scope);
