281:     /**
282:      * Get the {@link SqlSnapshot} node in a {@link SqlValidatorNamespace}.
283:      *
284:      * <p>In general, if there is a snapshot expression, the enclosing node of IdentifierNamespace
285:      * is usually SqlSnapshot. However, if we encounter a situation with an "as" operator, we need
286:      * to identify whether the enclosingNode is an "as" call and if its first operand is
287:      * SqlSnapshot.
288:      *
289:      * @param ns The namespace used to find SqlSnapshot
290:      * @return SqlSnapshot found in {@param ns}, empty if not found
291:      */
292:     private Optional<SqlSnapshot> getSnapShotNode(SqlValidatorNamespace ns) {
293:         if (ns instanceof IdentifierNamespace) {
294:             SqlNode enclosingNode = ns.getEnclosingNode();
295:             // FOR SYSTEM_TIME AS OF [expression]
296:             if (enclosingNode instanceof SqlSnapshot) {
297:                 return Optional.of((SqlSnapshot) enclosingNode);
298:                 // FOR SYSTEM_TIME AS OF [expression] as [identifier]
299:             } else if (enclosingNode instanceof SqlBasicCall
300:                     && ((SqlBasicCall) enclosingNode).getOperator() instanceof SqlAsOperator
301:                     && ((SqlBasicCall) enclosingNode).getOperandList().get(0)
302:                             instanceof SqlSnapshot) {
303:                 return Optional.of(
304:                         (SqlSnapshot) ((SqlBasicCall) enclosingNode).getOperandList().get(0));
305:             }
306:         }
307:         return Optional.empty();
308:     }
