320:     @Override
321:     protected void addToSelectList(
322:             List<SqlNode> list,
323:             Set<String> aliases,
324:             List<Map.Entry<String, RelDataType>> fieldList,
325:             SqlNode exp,
326:             SelectScope scope,
327:             boolean includeSystemVars) {
328:         // Extract column's origin to apply strategy
329:         if (!columnExpansionStrategies.isEmpty() && exp instanceof SqlIdentifier) {
330:             final SqlQualified qualified = scope.fullyQualify((SqlIdentifier) exp);
331:             if (qualified.namespace != null && qualified.namespace.getTable() != null) {
332:                 final CatalogSchemaTable schemaTable =
333:                         (CatalogSchemaTable) qualified.namespace.getTable().table();
334:                 final ResolvedSchema resolvedSchema =
335:                         schemaTable.getContextResolvedTable().getResolvedSchema();
336:                 final String columnName = qualified.suffix().get(0);
337:                 final Column column = resolvedSchema.getColumn(columnName).orElse(null);
338:                 if (qualified.suffix().size() == 1 && column != null) {
339:                     if (includeExpandedColumn(column, columnExpansionStrategies)
340:                             || declaredDescriptorColumn(scope, column)) {
341:                         super.addToSelectList(
342:                                 list, aliases, fieldList, exp, scope, includeSystemVars);
343:                     }
344:                     return;
345:                 }
346:             }
347:         }
348: 
349:         // Always add to list
350:         super.addToSelectList(list, aliases, fieldList, exp, scope, includeSystemVars);
351:     }
