215:             return of(configuration, null);
216:         }
217: 
218:         public static Settings of(
219:                 Configuration configuration,
220:                 @Nullable JobCheckpointingSettings checkpointingConfiguration)
221:                 throws ConfigurationException {
222:             final SchedulerExecutionMode executionMode =
223:                     configuration.get(JobManagerOptions.SCHEDULER_MODE);
224:             Duration allocationTimeoutDefault =
225:                     JobManagerOptions.RESOURCE_WAIT_TIMEOUT.defaultValue();
226:             Duration stabilizationTimeoutDefault =
227:                     JobManagerOptions.RESOURCE_STABILIZATION_TIMEOUT.defaultValue();
228:             if (executionMode == SchedulerExecutionMode.REACTIVE) {
229:                 allocationTimeoutDefault = Duration.ofMillis(-1);
230:                 stabilizationTimeoutDefault = Duration.ZERO;
231:             }
232: 
233:             final Duration scalingIntervalMin =
234:                     configuration.get(JobManagerOptions.SCHEDULER_SCALING_INTERVAL_MIN);
235: 
236:             final int rescaleOnFailedCheckpointsCount =
237:                     configuration.get(
238:                             JobManagerOptions.SCHEDULER_SCALE_ON_FAILED_CHECKPOINTS_COUNT);
239:             if (rescaleOnFailedCheckpointsCount < 1) {
240:                 throw new ConfigurationException(
241:                         String.format(
242:                                 "%s should have a value of 1 or higher.",
243:                                 JobManagerOptions.SCHEDULER_SCALE_ON_FAILED_CHECKPOINTS_COUNT
244:                                         .key()));
245:             }
246: 
247:             // default value generation is documented in JobManagerOption
248:             final Duration maximumDelayForRescaleTriggerDefault =
249:                     checkpointingConfiguration != null
250:                                     && checkpointingConfiguration
251:                                             .getCheckpointCoordinatorConfiguration()
252:                                             .isCheckpointingEnabled()
253:                             // incrementing the rescaleOnFailedCheckpointsCount by 1 is done to
254:                             // avoid introducing a race-condition between the two parameters
255:                             // (SCHEDULER_SCALE_ON_FAILED_CHECKPOINTS_COUNT and
256:                             // MAXIMUM_DELAY_FOR_SCALE_TRIGGER). Without the increment, we would
257:                             // have two configuration parameters that result in roughly the same
258:                             // timeout (with the MAXIMUM_DELAY_FOR_SCALE_TRIGGER being probably a
259:                             // bit faster). The user might experience unexpected behavior if the
260:                             // SCHEDULER_SCALE_ON_FAILED_CHECKPOINTS_COUNT is configured and
261:                             // MAXIMUM_DELAY_FOR_SCALE_TRIGGER is kept untouched in that case.
262:                             // Incrementing the default value should help avoiding causing this kind
263:                             // of confusing race condition.
264:                             ? Duration.ofMillis(
265:                                     (rescaleOnFailedCheckpointsCount + 1)
266:                                             * checkpointingConfiguration
267:                                                     .getCheckpointCoordinatorConfiguration()
268:                                                     .getCheckpointInterval())
269:                             : Duration.ZERO;
270: 
271:             if (configuration.getOptional(JobManagerOptions.MIN_PARALLELISM_INCREASE).isPresent()) {
272:                 LOG.warn(
273:                         "The configuration option {} is deprecated and will be removed in future versions. It's not used anymore. "
274:                                 + "Please use the configuration option {} and {} to control the sensitivity of a scaling operation.",
275:                         JobManagerOptions.MIN_PARALLELISM_INCREASE.key(),
276:                         JobManagerOptions.SCHEDULER_SCALING_INTERVAL_MIN.key(),
277:                         JobManagerOptions.SCHEDULER_SCALING_RESOURCE_STABILIZATION_TIMEOUT.key());
278:             }
279: 
280:             return new Settings(
281:                     executionMode,
282:                     configuration
283:                             .getOptional(JobManagerOptions.RESOURCE_WAIT_TIMEOUT)
284:                             .orElse(allocationTimeoutDefault),
285:                     configuration
286:                             .getOptional(JobManagerOptions.RESOURCE_STABILIZATION_TIMEOUT)
287:                             .orElse(stabilizationTimeoutDefault),
288:                     configuration.get(JobManagerOptions.SLOT_IDLE_TIMEOUT),
289:                     scalingIntervalMin,
290:                     configuration.get(
291:                             JobManagerOptions.SCHEDULER_SCALING_RESOURCE_STABILIZATION_TIMEOUT),
292:                     configuration.get(
293:                             MAXIMUM_DELAY_FOR_SCALE_TRIGGER, maximumDelayForRescaleTriggerDefault),
294:                     rescaleOnFailedCheckpointsCount);
295:         }
