589:     /**
590:      * Creates the parallelism store for a set of vertices, optionally with a flag to leave the
591:      * vertex parallelism unchanged. If the flag is set, the parallelisms must be valid for
592:      * execution.
593:      *
594:      * <p>We need to set parallelism to the max possible value when requesting resources, but when
595:      * executing the graph we should respect what we are actually given.
596:      *
597:      * @param vertices The vertices to store parallelism information for
598:      * @param adjustParallelism Whether to adjust the parallelism
599:      * @param defaultMaxParallelismFunc a function for computing a default max parallelism if none
600:      *     is specified on a given vertex
601:      * @return The parallelism store.
602:      */
603:     @VisibleForTesting
604:     static VertexParallelismStore computeReactiveModeVertexParallelismStore(
605:             Iterable<JobVertex> vertices,
606:             Function<JobVertex, Integer> defaultMaxParallelismFunc,
607:             boolean adjustParallelism) {
608:         DefaultVertexParallelismStore store = new DefaultVertexParallelismStore();
609: 
610:         for (JobVertex vertex : vertices) {
611:             // if no max parallelism was configured by the user, we calculate and set a default
612:             final int maxParallelism =
613:                     vertex.getMaxParallelism() == JobVertex.MAX_PARALLELISM_DEFAULT
614:                             ? defaultMaxParallelismFunc.apply(vertex)
615:                             : vertex.getMaxParallelism();
616:             // If the parallelism has already been adjusted, respect what has been configured in the
617:             // vertex. Otherwise, scale it to the max parallelism to attempt to be "as parallel as
618:             // possible"
619:             final int parallelism;
620:             if (adjustParallelism) {
621:                 parallelism = maxParallelism;
622:             } else {
623:                 parallelism = vertex.getParallelism();
624:             }
625: 
626:             VertexParallelismInformation parallelismInfo =
627:                     new DefaultVertexParallelismInfo(
628:                             parallelism,
629:                             maxParallelism,
630:                             // Allow rescaling if the new desired max parallelism
631:                             // is not less than what was declared here during scheduling.
632:                             // This prevents the situation where more resources are requested
633:                             // based on the computed default, when actually fewer are necessary.
634:                             (newMax) ->
635:                                     newMax >= maxParallelism
636:                                             ? Optional.empty()
637:                                             : Optional.of(
638:                                                     "Cannot lower max parallelism in Reactive mode."));
639:             store.setParallelismInfo(vertex.getID(), parallelismInfo);
640:         }
641: 
642:         return store;
643:     }
