767:     private CompletableFuture<Map<String, String>> labelFailure(
768:             final TaskExecutionStateTransition taskExecutionStateTransition) {
769:         if (taskExecutionStateTransition.getExecutionState() == ExecutionState.FAILED
770:                 && !failureEnrichers.isEmpty()) {
771:             final Throwable cause = taskExecutionStateTransition.getError(userCodeClassLoader);
772:             final Context ctx =
773:                     DefaultFailureEnricherContext.forTaskFailure(
774:                             jobInfo, jobManagerJobMetricGroup, ioExecutor, userCodeClassLoader);
775:             return FailureEnricherUtils.labelFailure(
776:                     cause, ctx, getMainThreadExecutor(), failureEnrichers);
777:         }
778:         return FailureEnricherUtils.EMPTY_FAILURE_LABELS;
779:     }
