1533:     /**
1534:      * Transition the scheduler to another state. This method guards against state transitions while
1535:      * there is already a transition ongoing. This effectively means that you can not call this
1536:      * method from a State constructor or State#onLeave.
1537:      *
1538:      * @param targetState State to transition to
1539:      * @param <T> Type of the target state
1540:      * @return A target state instance
1541:      */
1542:     @VisibleForTesting
1543:     <T extends State> T transitionToState(StateFactory<T> targetState) {
1544:         Preconditions.checkState(
1545:                 !isTransitioningState,
1546:                 "State transitions must not be triggered while another state transition is in progress.");
1547:         Preconditions.checkState(
1548:                 state.getClass() != targetState.getStateClass(),
1549:                 "Attempted to transition into the very state the scheduler is already in.");
1550:         componentMainThreadExecutor.assertRunningInMainThread();
1551: 
1552:         try {
1553:             isTransitioningState = true;
1554:             LOG.debug(
1555:                     "Transition from state {} to {}.",
