1645:                                                 callback,
1646:                                                 logger ->
1647:                                                         logger.debug(
1648:                                                                 "{} is not supported by {}.",
1649:                                                                 callbackLabel,
1650:                                                                 state.getClass().getName())));
1651:             }
1652:         };
1653:     }
