1361:     @Override
1362:     public CreatingExecutionGraph.AssignmentResult tryToAssignSlots(
1363:             CreatingExecutionGraph.ExecutionGraphWithVertexParallelism
1364:                     executionGraphWithVertexParallelism) {
1365:         final ExecutionGraph executionGraph =
1366:                 executionGraphWithVertexParallelism.getExecutionGraph();
1367: 
1368:         executionGraph.start(componentMainThreadExecutor);
1369: 
1370:         executionGraph.setInternalTaskFailuresListener(
1371:                 new UpdateSchedulerNgOnInternalFailuresListener(this));
1372: 
1373:         final JobSchedulingPlan jobSchedulingPlan =
1374:                 executionGraphWithVertexParallelism.getJobSchedulingPlan();
1375:         return slotAllocator
1376:                 .tryReserveResources(jobSchedulingPlan)
1377:                 .map(reservedSlots -> assignSlotsToExecutionGraph(executionGraph, reservedSlots))
1378:                 .map(CreatingExecutionGraph.AssignmentResult::success)
1379:                 .orElseGet(CreatingExecutionGraph.AssignmentResult::notPossible);
1380:     }
1381: 
1382:     @Nonnull
1383:     private ExecutionGraph assignSlotsToExecutionGraph(
1384:             ExecutionGraph executionGraph, ReservedSlots reservedSlots) {
1385:         for (ExecutionVertex executionVertex : executionGraph.getAllExecutionVertices()) {
1386:             final LogicalSlot assignedSlot = reservedSlots.getSlotFor(executionVertex.getID());
1387:             final CompletableFuture<Void> registrationFuture =
1388:                     executionVertex
1389:                             .getCurrentExecutionAttempt()
1390:                             .registerProducedPartitions(assignedSlot.getTaskManagerLocation());
1391:             Preconditions.checkState(
1392:                     registrationFuture.isDone(),
1393:                     "Partition registration must be completed immediately for reactive mode");
1394: 
1395:             executionVertex.tryAssignResource(assignedSlot);
1396:         }
1397: 
1398:         return executionGraph;
1399:     }
