724:     private void stopCheckpointServicesSafely(JobStatus terminalState) {
725:         LOG.debug("Stopping the checkpoint services with state {}.", terminalState);
726: 
727:         Exception exception = null;
728: 
729:         try {
730:             completedCheckpointStore.shutdown(terminalState, checkpointsCleaner);
731:         } catch (Exception e) {
732:             exception = e;
733:         }
734: 
735:         try {
736:             checkpointIdCounter.shutdown(terminalState).get();
737:         } catch (Exception e) {
738:             exception = ExceptionUtils.firstOrSuppressed(e, exception);
739:         }
740: 
741:         if (exception != null) {
742:             LOG.warn("Failed to stop checkpoint services.", exception);
743:         }
744:     }
