645:     /**
646:      * Creates the parallelism store that should be used for determining scheduling requirements,
647:      * which may choose different parallelisms than set in the {@link JobGraph} depending on the
648:      * execution mode.
649:      *
650:      * @param jobGraph The job graph for execution.
651:      * @param executionMode The mode of scheduler execution.
652:      * @return The parallelism store.
653:      */
654:     private static VertexParallelismStore computeVertexParallelismStore(
655:             JobGraph jobGraph, SchedulerExecutionMode executionMode) {
656:         if (executionMode == SchedulerExecutionMode.REACTIVE) {
657:             return computeReactiveModeVertexParallelismStore(
658:                     jobGraph.getVertices(), SchedulerBase::getDefaultMaxParallelism, true);
659:         }
660:         return SchedulerBase.computeVertexParallelismStore(jobGraph);
661:     }
