1586:     /**
1587:      * Check for slots that are idle for more than {@link JobManagerOptions#SLOT_IDLE_TIMEOUT} and
1588:      * release them back to the ResourceManager.
1589:      */
1590:     private void checkIdleSlotTimeout() {
1591:         if (getState().getJobStatus().isGloballyTerminalState()) {
1592:             // Job has reached the terminal state, so we can return all slots to the ResourceManager
1593:             // to speed things up because we no longer need them. This optimization lets us skip
1594:             // waiting for the slot pool service to close.
1595:             for (SlotInfo slotInfo : declarativeSlotPool.getAllSlotsInformation()) {
1596:                 declarativeSlotPool.releaseSlot(
1597:                         slotInfo.getAllocationId(),
1598:                         new FlinkException(
1599:                                 "Returning slots to their owners, because the job has reached a globally terminal state."));
1600:             }
1601:             return;
1602:         } else if (getState().getJobStatus().isTerminalState()) {
1603:             // do nothing
1604:             // prevent idleness check running again while scheduler was already shut down
1605:             // don't release slots because JobMaster may want to hold on to slots in case
1606:             // it re-acquires leadership
1607:             return;
1608:         }
1609:         declarativeSlotPool.releaseIdleSlots(System.currentTimeMillis());
1610:         getMainThreadExecutor()
1611:                 .schedule(
1612:                         this::checkIdleSlotTimeout,
1613:                         settings.getSlotIdleTimeout().toMillis(),
1614:                         TimeUnit.MILLISECONDS);
1615:     }
