196:      *     Supplier, Duration, Duration, Duration)
197:      */
198:     @FunctionalInterface
199:     interface StateTransitionManagerFactory {
200:         StateTransitionManager create(
201:                 StateTransitionManager.Context context,
202:                 Supplier<Temporal> clock,
203:                 Duration cooldownTimeout,
204:                 Duration resourceStabilizationTimeout,
205:                 Duration maximumDelayForRescaleTrigger);
206:     }
