1619:      * events are actually executed in the {@code AdaptiveScheduler}'s main thread.
1620:      */
1621:     private CheckpointStatsListener createCheckpointStatsListener() {
1622: 
1623:         return new CheckpointStatsListener() {
1624: 
1625:             @Override
1626:             public void onFailedCheckpoint() {
1627:                 runIfSupported(CheckpointStatsListener::onFailedCheckpoint, "onFailedCheckpoint");
1628:             }
1629: 
1630:             @Override
1631:             public void onCompletedCheckpoint() {
1632:                 runIfSupported(
1633:                         CheckpointStatsListener::onCompletedCheckpoint, "onCompletedCheckpoint");
1634:             }
1635: 
1636:             private void runIfSupported(
1637:                     ThrowingConsumer<CheckpointStatsListener, RuntimeException> callback,
1638:                     String callbackLabel) {
1639:                 AdaptiveScheduler.this
1640:                         .getMainThreadExecutor()
1641:                         .execute(
1642:                                 () ->
1643:                                         state.tryRun(
1644:                                                 CheckpointStatsListener.class,
1645:                                                 callback,
1646:                                                 logger ->
1647:                                                         logger.debug(
1648:                                                                 "{} is not supported by {}.",
1649:                                                                 callbackLabel,
1650:                                                                 state.getClass().getName())));
1651:             }
1652:         };
1653:     }
