371:     private List<SETUP> setupReporters(
372:             Map<String, REPORTER_FACTORY> reporterFactories,
373:             List<Tuple2<String, Configuration>> reporterConfigurations) {
374:         List<SETUP> reporterSetups = new ArrayList<>(reporterConfigurations.size());
375:         for (Tuple2<String, Configuration> reporterConfiguration : reporterConfigurations) {
376:             String reporterName = reporterConfiguration.f0;
377:             Configuration reporterConfig = reporterConfiguration.f1;
378: 
379:             try {
380:                 Optional<REPORTER> metricReporterOptional =
381:                         loadReporter(reporterName, reporterConfig, reporterFactories);
382: 
383:                 final MetricFilter metricFilter =
384:                         DefaultMetricFilter.fromConfiguration(reporterConfig);
385: 
386:                 // massage user variables keys into scope format for parity to variable
387:                 // exclusion
388:                 Map<String, String> additionalVariables =
389:                         reporterConfig.get(reporterSetupInfo.reporterAdditionalVariables).entrySet()
390:                                 .stream()
391:                                 .collect(
392:                                         Collectors.toMap(
393:                                                 e -> ScopeFormat.asVariable(e.getKey()),
394:                                                 Map.Entry::getValue));
395: 
396:                 metricReporterOptional.ifPresent(
397:                         reporter -> {
398:                             MetricConfig metricConfig = new MetricConfig();
399:                             reporterConfig.addAllToProperties(metricConfig);
400:                             reporterSetups.add(
401:                                     createReporterSetup(
402:                                             reporterName,
403:                                             metricConfig,
404:                                             reporter,
405:                                             metricFilter,
406:                                             additionalVariables));
407:                         });
408:             } catch (Throwable t) {
409:                 LOG.error(
410:                         "Could not instantiate {} {}. Reporting might not be exposed.",
411:                         reporterSetupInfo.reporterTypeClass.getSimpleName(),
412:                         reporterName,
413:                         t);
414:             }
415:         }
416:         return reporterSetups;
417:     }
