457:     private Optional<REPORTER> loadViaFactory(
458:             final Configuration reporterConfig, final REPORTER_FACTORY factory) {
459: 
460:         final MetricConfig metricConfig = new MetricConfig();
461:         reporterConfig.addAllToProperties(metricConfig);
462: 
463:         return Optional.of(reporterSetupInfo.reporterFactoryAdapter.invoke(factory, metricConfig));
464:     }
