1328:     @Override
1329:     public void goToCreatingExecutionGraph(@Nullable ExecutionGraph previousExecutionGraph) {
1330:         final CompletableFuture<CreatingExecutionGraph.ExecutionGraphWithVertexParallelism>
1331:                 executionGraphWithAvailableResourcesFuture =
1332:                         createExecutionGraphWithAvailableResourcesAsync(previousExecutionGraph);
1333:         transitionToState(
1334:                 new CreatingExecutionGraph.Factory(
1335:                         this,
1336:                         executionGraphWithAvailableResourcesFuture,
1337:                         LOG,
1338:                         previousExecutionGraph));
1339:     }
