715:     @Override
716:     public CompletableFuture<Void> closeAsync() {
717:         LOG.debug("Closing the AdaptiveScheduler. Trying to suspend the current job execution.");
718: 
719:         currentState.suspend(new FlinkException("AdaptiveScheduler is being stopped."));
720: 
721:         Preconditions.checkState(
722:                 currentState instanceof Finished,
723:                 "Scheduler state should be finished after calling state.suspend.");
724: 
725:         backgroundTask.abort();
726:         // wait for the background task to finish and then close services
727:         return FutureUtils.composeAfterwards(
728:                 FutureUtils.runAfterwardsAsync(
729:                         backgroundTask.getTerminationFuture(),
730:                         () -> stopCheckpointServicesSafely(jobTerminationFuture.get()),
731:                         getMainThreadExecutor()),
732:                 checkpointsCleaner::closeAsync);
733:     }
