197:      *     Supplier, Duration, Duration, Duration)
198:      */
199:     @FunctionalInterface
200:     interface StateTransitionManagerFactory {
201:         StateTransitionManager create(
202:                 StateTransitionManager.Context context,
203:                 Supplier<Temporal> clock,
204:                 Duration cooldownTimeout,
205:                 Duration resourceStabilizationTimeout,
206:                 Duration maximumDelayForTrigger);
207:     }
