1554:     /**
1555:      * Transition the scheduler to another state. This method guards against state transitions while
1556:      * there is already a transition ongoing. This effectively means that you can not call this
1557:      * method from a State constructor or State#onLeave.
1558:      *
1559:      * @param targetState State to transition to
1560:      * @param <T> Type of the target state
1561:      * @return A target state instance
1562:      */
1563:     @VisibleForTesting
1564:     <T extends State> T transitionToState(StateFactory<T> targetState) {
1565:         Preconditions.checkState(
1566:                 !isTransitioningState,
1567:                 "State transitions must not be triggered while another state transition is in progress.");
1568:         Preconditions.checkState(
1569:                 currentState.getClass() != targetState.getStateClass(),
1570:                 "Attempted to transition into the very state the scheduler is already in.");
1571:         componentMainThreadExecutor.assertRunningInMainThread();
1572: 
1573:         try {
1574:             isTransitioningState = true;
1575:             LOG.debug(
1576:                     "Transition from state {} to {}.",
1577:                     currentState.getClass().getSimpleName(),
1578:                     targetState.getStateClass().getSimpleName());
1579: 
1580:             final JobStatus previousJobStatus = currentState.getJobStatus();
1581: 
1582:             currentState.onLeave(targetState.getStateClass());
1583:             T targetStateInstance = targetState.getState();
1584:             currentState = targetStateInstance;
1585: 
1586:             final JobStatus newJobStatus = currentState.getJobStatus();
1587: 
1588:             if (previousJobStatus != newJobStatus) {
1589:                 final long timestamp = System.currentTimeMillis();
1590:                 jobStatusListeners.forEach(
1591:                         listener ->
1592:                                 listener.jobStatusChanges(
1593:                                         jobInformation.getJobID(), newJobStatus, timestamp));
1594:             }
1595: 
1596:             return targetStateInstance;
1597:         } finally {
1598:             isTransitioningState = false;
1599:         }
1600:     }
