1607:     /**
1608:      * Check for slots that are idle for more than {@link JobManagerOptions#SLOT_IDLE_TIMEOUT} and
1609:      * release them back to the ResourceManager.
1610:      */
1611:     private void checkIdleSlotTimeout() {
1612:         if (getState().getJobStatus().isGloballyTerminalState()) {
1613:             // Job has reached the terminal state, so we can return all slots to the ResourceManager
1614:             // to speed things up because we no longer need them. This optimization lets us skip
1615:             // waiting for the slot pool service to close.
1616:             for (SlotInfo slotInfo : declarativeSlotPool.getAllSlotsInformation()) {
1617:                 declarativeSlotPool.releaseSlot(
1618:                         slotInfo.getAllocationId(),
1619:                         new FlinkException(
1620:                                 "Returning slots to their owners, because the job has reached a globally terminal state."));
1621:             }
1622:             return;
1623:         } else if (getState().getJobStatus().isTerminalState()) {
1624:             // do nothing
1625:             // prevent idleness check running again while scheduler was already shut down
1626:             // don't release slots because JobMaster may want to hold on to slots in case
1627:             // it re-acquires leadership
1628:             return;
1629:         }
1630:         declarativeSlotPool.releaseIdleSlots(System.currentTimeMillis());
1631:         getMainThreadExecutor()
1632:                 .schedule(
1633:                         this::checkIdleSlotTimeout,
1634:                         schedulerSettings.getSlotIdleTimeout().toMillis(),
1635:                         TimeUnit.MILLISECONDS);
1636:     }
