735:     private void stopCheckpointServicesSafely(JobStatus terminalState) {
736:         LOG.debug("Stopping the checkpoint services with state {}.", terminalState);
737: 
738:         Exception exception = null;
739: 
740:         try {
741:             completedCheckpointStore.shutdown(terminalState, checkpointsCleaner);
742:         } catch (Exception e) {
743:             exception = e;
744:         }
745: 
746:         try {
747:             checkpointIdCounter.shutdown(terminalState).get();
748:         } catch (Exception e) {
749:             exception = ExceptionUtils.firstOrSuppressed(e, exception);
750:         }
751: 
752:         if (exception != null) {
753:             LOG.warn("Failed to stop checkpoint services.", exception);
754:         }
755:     }
