1381:     @Override
1382:     public CreatingExecutionGraph.AssignmentResult tryToAssignSlots(
1383:             CreatingExecutionGraph.ExecutionGraphWithVertexParallelism
1384:                     executionGraphWithVertexParallelism) {
1385:         final ExecutionGraph executionGraph =
1386:                 executionGraphWithVertexParallelism.getExecutionGraph();
1387: 
1388:         executionGraph.start(componentMainThreadExecutor);
1389: 
1390:         executionGraph.setInternalTaskFailuresListener(
1391:                 new UpdateSchedulerNgOnInternalFailuresListener(this));
1392: 
1393:         final JobSchedulingPlan jobSchedulingPlan =
1394:                 executionGraphWithVertexParallelism.getJobSchedulingPlan();
1395:         return slotAllocator
1396:                 .tryReserveResources(jobSchedulingPlan)
1397:                 .map(reservedSlots -> assignSlotsToExecutionGraph(executionGraph, reservedSlots))
1398:                 .map(CreatingExecutionGraph.AssignmentResult::success)
1399:                 .orElseGet(CreatingExecutionGraph.AssignmentResult::notPossible);
1400:     }
1401: 
1402:     @Nonnull
1403:     private ExecutionGraph assignSlotsToExecutionGraph(
1404:             ExecutionGraph executionGraph, ReservedSlots reservedSlots) {
1405:         for (ExecutionVertex executionVertex : executionGraph.getAllExecutionVertices()) {
1406:             final LogicalSlot assignedSlot = reservedSlots.getSlotFor(executionVertex.getID());
1407:             final CompletableFuture<Void> registrationFuture =
1408:                     executionVertex
1409:                             .getCurrentExecutionAttempt()
1410:                             .registerProducedPartitions(assignedSlot.getTaskManagerLocation());
1411:             Preconditions.checkState(
1412:                     registrationFuture.isDone(),
1413:                     "Partition registration must be completed immediately for reactive mode");
1414: 
1415:             executionVertex.tryAssignResource(assignedSlot);
1416:         }
1417: 
1418:         return executionGraph;
1419:     }
