1341:     private CompletableFuture<CreatingExecutionGraph.ExecutionGraphWithVertexParallelism>
1342:             createExecutionGraphWithAvailableResourcesAsync(
1343:                     @Nullable ExecutionGraph previousExecutionGraph) {
1344:         final JobSchedulingPlan schedulingPlan;
1345:         final VertexParallelismStore adjustedParallelismStore;
1346: 
1347:         try {
1348:             schedulingPlan = determineParallelism(slotAllocator, previousExecutionGraph);
1349:             JobGraph adjustedJobGraph = jobResourceRequirementsInfo.copyJobGraph();
1350: 
1351:             for (JobVertex vertex : adjustedJobGraph.getVertices()) {
1352:                 JobVertexID id = vertex.getID();
1353: 
1354:                 // use the determined "available parallelism" to use
1355:                 // the resources we have access to
1356:                 vertex.setParallelism(schedulingPlan.getVertexParallelism().getParallelism(id));
1357:             }
1358: 
1359:             // use the originally configured max parallelism
1360:             // as the default for consistent runs
1361:             adjustedParallelismStore =
1362:                     computeVertexParallelismStoreForExecution(
1363:                             adjustedJobGraph,
1364:                             schedulerSettings.getExecutionMode(),
1365:                             (vertex) -> {
1366:                                 VertexParallelismInformation vertexParallelismInfo =
1367:                                         initialParallelismStore.getParallelismInfo(vertex.getID());
1368:                                 return vertexParallelismInfo.getMaxParallelism();
1369:                             });
1370:         } catch (Exception exception) {
1371:             return FutureUtils.completedExceptionally(exception);
1372:         }
1373: 
1374:         return createExecutionGraphAndRestoreStateAsync(adjustedParallelismStore)
1375:                 .thenApply(
1376:                         executionGraph ->
1377:                                 CreatingExecutionGraph.ExecutionGraphWithVertexParallelism.create(
1378:                                         executionGraph, schedulingPlan));
1379:     }
