1397:                 .map(reservedSlots -> assignSlotsToExecutionGraph(executionGraph, reservedSlots))
1398:                 .map(CreatingExecutionGraph.AssignmentResult::success)
1399:                 .orElseGet(CreatingExecutionGraph.AssignmentResult::notPossible);
