1493:     private FailureResult howToHandleFailure(Throwable failure) {
1494:         if (ExecutionFailureHandler.isUnrecoverableError(failure)) {
1495:             return FailureResult.canNotRestart(
1496:                     new JobException("The failure is not recoverable", failure));
1497:         }
1498: 
1499:         restartBackoffTimeStrategy.notifyFailure(failure);
1500:         if (restartBackoffTimeStrategy.canRestart()) {
1501:             return FailureResult.canRestart(
1502:                     failure, Duration.ofMillis(restartBackoffTimeStrategy.getBackoffTime()));
1503:         } else {
1504:             return FailureResult.canNotRestart(
1505:                     new JobException(
1506:                             "Recovery is suppressed by " + restartBackoffTimeStrategy, failure));
1507:         }
1508:     }
