378:     private TestingMiniClusterConfiguration getMiniClusterConfiguration(Configuration config)
379:             throws IOException {
380:         // flink basic configuration.
381:         NetUtils.Port jobManagerRpcPort = NetUtils.getAvailablePort();
382:         flinkConfiguration.set(ExecutionOptions.RUNTIME_MODE, RuntimeExecutionMode.BATCH);
383:         flinkConfiguration.set(JobManagerOptions.PORT, jobManagerRpcPort.getPort());
384:         flinkConfiguration.set(JobManagerOptions.SLOT_REQUEST_TIMEOUT, Duration.ofMillis(5000L));
385:         flinkConfiguration.set(RestOptions.BIND_PORT, "0");
386:         flinkConfiguration.set(TaskManagerOptions.TOTAL_PROCESS_MEMORY, MemorySize.parse("1g"));
387:         flinkConfiguration.set(TaskManagerOptions.NETWORK_MEMORY_FRACTION, 0.4F);
388: 
389:         // adaptive batch job scheduler config.
390:         flinkConfiguration.set(
391:                 JobManagerOptions.SCHEDULER, JobManagerOptions.SchedulerType.AdaptiveBatch);
392:         flinkConfiguration.set(
393:                 BatchExecutionOptions.ADAPTIVE_AUTO_PARALLELISM_MAX_PARALLELISM,
394:                 DEFAULT_MAX_PARALLELISM);
395:         flinkConfiguration.set(
396:                 BatchExecutionOptions.ADAPTIVE_AUTO_PARALLELISM_AVG_DATA_VOLUME_PER_TASK,
397:                 MemorySize.parse("256K"));
398: 
399:         // enable jm failover.
400:         flinkConfiguration.set(BatchExecutionOptions.JOB_RECOVERY_ENABLED, true);
401:         flinkConfiguration.set(
402:                 BatchExecutionOptions.JOB_RECOVERY_SNAPSHOT_MIN_PAUSE, Duration.ZERO);
403: 
404:         // region failover config.
405:         flinkConfiguration.set(JobManagerOptions.EXECUTION_FAILOVER_STRATEGY, "region");
406:         flinkConfiguration.set(RestartStrategyOptions.RESTART_STRATEGY, "fixed-delay");
407:         flinkConfiguration.set(RestartStrategyOptions.RESTART_STRATEGY_FIXED_DELAY_ATTEMPTS, 10);
408: 
409:         // ha config, which helps to trigger jm failover.
410:         flinkConfiguration.set(HighAvailabilityOptions.HA_STORAGE_PATH, temporaryFolder.toString());
411:         highAvailabilityServices =
412:                 new EmbeddedHaServicesWithLeadershipControl(EXECUTOR_EXTENSION.getExecutor());
413:         highAvailabilityServicesSupplier = () -> highAvailabilityServices;
414: 
415:         // shuffle dir, to help trigger partitionNotFoundException
416:         flinkConfiguration.set(CoreOptions.TMP_DIRS, temporaryFolder.toString());
417: 
418:         // add user defined config
419:         flinkConfiguration.addAll(config);
420: 
421:         return TestingMiniClusterConfiguration.newBuilder()
422:                 .setConfiguration(flinkConfiguration)
423:                 .setNumTaskManagers(numTaskManagers)
424:                 .setNumSlotsPerTaskManager(numSlotsPerTaskManager)
425:                 .build();
426:     }
