695:     /** A special sink function which can control the task's execution. */
696:     private static class StubRecordSink extends AbstractStreamOperator<Void>
697:             implements OneInputStreamOperator<Tuple2<Integer, Integer>, Void> {
698: 
699:         public static Map<Integer, Boolean> subtaskBlocked = new ConcurrentHashMap<>();
700:         public static Map<Integer, Integer> attemptIds = new ConcurrentHashMap<>();
701:         public static Map<Integer, Integer> countResults = new ConcurrentHashMap<>();
702: 
703:         @Override
704:         protected void setup(
705:                 StreamTask<?, ?> containingTask,
706:                 StreamConfig config,
707:                 Output<StreamRecord<Void>> output) {
708:             super.setup(containingTask, config, output);
709: 
710:             int subIdx = getRuntimeContext().getTaskInfo().getIndexOfThisSubtask();
711: 
712:             // attempt id ++
713:             attemptIds.compute(
714:                     subIdx,
715:                     (ignored, value) -> {
716:                         if (value == null) {
717:                             value = 0;
718:                         } else {
719:                             value += 1;
720:                         }
721:                         return value;
722:                     });
723: 
724:             // wait until unblocked.
725:             if (subtaskBlocked.containsKey(subIdx) && subtaskBlocked.get(subIdx)) {
726:                 tryWaitUntilCondition(() -> !subtaskBlocked.get(subIdx));
727:             }
728:         }
729: 
730:         @Override
731:         public void processElement(StreamRecord<Tuple2<Integer, Integer>> streamRecord)
732:                 throws Exception {
733:             Tuple2<Integer, Integer> value = streamRecord.getValue();
734:             countResults.put(value.f0, value.f1);
735:         }
736: 
737:         public static void clear() {
738:             subtaskBlocked.clear();
739:             attemptIds.clear();
740:             countResults.clear();
741:         }
742: 
743:         public static void blockSubTasks(Integer... subIndices) {
744:             setSubtaskBlocked(Arrays.asList(subIndices), true, subtaskBlocked);
745:         }
746: 
747:         public static void unblockSubTasks(Integer... subIndices) {
748:             setSubtaskBlocked(Arrays.asList(subIndices), false, subtaskBlocked);
749:         }
750:     }
751: 
752:     private static void tryWaitUntilCondition(SupplierWithException<Boolean, Exception> condition) {
753:         try {
754:             CommonTestUtils.waitUntilCondition(condition);
755:         } catch (Exception exception) {
756:         }
757:     }
