760:         try (FileWriter writer = new FileWriter(datafile)) {
761:             for (int i = 0; i < NUMBER_KEYS * NUMBER_OF_EACH_KEY; i++) {
762:                 writer.write(i + "\n");
763:             }
764:         }
765:         return datafile;
766:     }
