382:         flinkConfiguration.set(ExecutionOptions.RUNTIME_MODE, RuntimeExecutionMode.BATCH);
383:         flinkConfiguration.set(JobManagerOptions.PORT, jobManagerRpcPort.getPort());
384:         flinkConfiguration.set(JobManagerOptions.SLOT_REQUEST_TIMEOUT, Duration.ofMillis(5000L));
385:         flinkConfiguration.set(RestOptions.BIND_PORT, "0");
386:         flinkConfiguration.set(TaskManagerOptions.TOTAL_PROCESS_MEMORY, MemorySize.parse("1g"));
387:         flinkConfiguration.set(TaskManagerOptions.NETWORK_MEMORY_FRACTION, 0.4F);
388: 
389:         // adaptive batch job scheduler config.
390:         flinkConfiguration.set(
391:                 JobManagerOptions.SCHEDULER, JobManagerOptions.SchedulerType.AdaptiveBatch);
392:         flinkConfiguration.set(
393:                 BatchExecutionOptions.ADAPTIVE_AUTO_PARALLELISM_MAX_PARALLELISM,
394:                 DEFAULT_MAX_PARALLELISM);
395:         flinkConfiguration.set(
396:                 BatchExecutionOptions.ADAPTIVE_AUTO_PARALLELISM_AVG_DATA_VOLUME_PER_TASK,
397:                 MemorySize.parse("256K"));
