449:     private JobGraph createJobGraph(StreamExecutionEnvironment env, String jobName) {
450:         TupleTypeInfo<Tuple2<Integer, Integer>> typeInfo =
451:                 new TupleTypeInfo<>(BasicTypeInfo.INT_TYPE_INFO, BasicTypeInfo.INT_TYPE_INFO);
452: 
453:         env.fromSequence(0, NUMBER_KEYS * NUMBER_OF_EACH_KEY - 1)
454:                 .setParallelism(SOURCE_PARALLELISM)
455:                 .slotSharingGroup("group1")
456:                 .transform("SourceTail", TypeInformation.of(Long.class), new SourceTail())
457:                 .setParallelism(SOURCE_PARALLELISM)
458:                 .slotSharingGroup("group1")
459:                 .transform("Map", typeInfo, new StubMapFunction())
460:                 .slotSharingGroup("group2")
461:                 .keyBy(tuple2 -> tuple2.f0)
462:                 .sum(1)
463:                 .slotSharingGroup("group3")
464:                 .transform("Sink", TypeInformation.of(Void.class), new StubRecordSink())
465:                 .slotSharingGroup("group4");
466: 
467:         StreamGraph streamGraph = env.getStreamGraph();
468:         streamGraph.setGlobalStreamExchangeMode(GlobalStreamExchangeMode.ALL_EDGES_BLOCKING);
469:         streamGraph.setJobType(JobType.BATCH);
470:         streamGraph.setJobName(jobName);
