360:     private JobGraph prepareBatchEnvAndGenerateJobGraph(
361:             Configuration config, boolean operatorCoordinatorsSupportsBatchSnapshot)
362:             throws Exception {
363:         flinkCluster =
364:                 TestingMiniCluster.newBuilder(getMiniClusterConfiguration(config))
365:                         .setHighAvailabilityServicesSupplier(highAvailabilityServicesSupplier)
366:                         .build();
367:         flinkCluster.start();
368: 
369:         final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
370:         env.setParallelism(-1);
371:         env.setRuntimeMode(RuntimeExecutionMode.BATCH);
372: 
373:         return operatorCoordinatorsSupportsBatchSnapshot
374:                 ? createBatchJobGraph(env, methodName)
375:                 : createBatchJobGraphWithUnsupportedOperatorCoordinator(env, methodName);
376:     }
