474:     private JobGraph createBatchJobGraphWithUnsupportedOperatorCoordinator(
475:             StreamExecutionEnvironment env, String jobName) throws Exception {
476: 
477:         TupleTypeInfo<Tuple2<Integer, Integer>> typeInfo =
478:                 new TupleTypeInfo<>(BasicTypeInfo.INT_TYPE_INFO, BasicTypeInfo.INT_TYPE_INFO);
479: 
480:         File file = new File(temporaryFolder.getParent().toFile(), "data.tmp-" + UUID.randomUUID());
481:         prepareTestData(file);
482: 
483:         FileSource<String> source =
484:                 FileSource.forRecordStreamFormat(
485:                                 new TextLineInputFormat(), new Path(file.getPath()))
486:                         .build();
487: 
488:         env.fromSource(source, WatermarkStrategy.noWatermarks(), "source")
489:                 .setParallelism(SOURCE_PARALLELISM)
490:                 .slotSharingGroup("group1")
491:                 .transform("Map", typeInfo, new StubMapFunction2())
492:                 .slotSharingGroup("group2")
493:                 .keyBy(tuple2 -> tuple2.f0)
494:                 .sum(1)
495:                 .slotSharingGroup("group3")
496:                 .transform("Sink", TypeInformation.of(Void.class), new StubRecordSink())
497:                 .slotSharingGroup("group4");
498: 
499:         StreamGraph streamGraph = env.getStreamGraph();
500:         streamGraph.setGlobalStreamExchangeMode(GlobalStreamExchangeMode.ALL_EDGES_BLOCKING);
501:         streamGraph.setJobType(JobType.BATCH);
502:         streamGraph.setJobName(jobName);
503:         return StreamingJobGraphGenerator.createJobGraph(streamGraph);
