121:  * instance of {@link MiniCluster} per test, we suggest you to instantiate it manually in your test
122:  * code.
123:  *
124:  * <p>This extension works correctly with parallel tests and with parametrized tests, but it doesn't
125:  * work when combining {@link TestFactory} and parallel tests, because of <a
126:  * href="https://github.com/junit-team/junit5/issues/378">some limitations</a>. Use {@link
127:  * ParameterizedTest} instead.
128:  */
129: @Experimental
130: public final class MiniClusterExtension
131:         implements BeforeAllCallback,
132:                 BeforeEachCallback,
133:                 AfterEachCallback,
134:                 AfterAllCallback,
135:                 ParameterResolver {
136: 
137:     private static final ExtensionContext.Namespace NAMESPACE =
138:             ExtensionContext.Namespace.create(MiniClusterExtension.class);
139: 
140:     private static final String CLUSTER_REST_CLIENT = "clusterRestClient";
141:     private static final String MINI_CLUSTER_CLIENT = "miniClusterClient";
142: 
143:     private final Supplier<MiniClusterResourceConfiguration>
144:             miniClusterResourceConfigurationSupplier;
145: 
146:     private InternalMiniClusterExtension internalMiniClusterExtension;
147: 
148:     private TestEnvironment streamTestEnvironment;
149: 
150:     public MiniClusterExtension() {
151:         this(
152:                 new MiniClusterResourceConfiguration.Builder()
153:                         .setNumberTaskManagers(1)
154:                         .setNumberSlotsPerTaskManager(1)
155:                         .build());
156:     }
157: 
158:     public MiniClusterExtension(
159:             final MiniClusterResourceConfiguration miniClusterResourceConfiguration) {
160:         this(() -> miniClusterResourceConfiguration);
161:     }
162: 
163:     @Experimental
164:     public MiniClusterExtension(
165:             Supplier<MiniClusterResourceConfiguration> miniClusterResourceConfigurationSupplier) {
166:         this.miniClusterResourceConfigurationSupplier = miniClusterResourceConfigurationSupplier;
167:     }
168: 
169:     // Accessors
170: 
171:     @Override
172:     public boolean supportsParameter(
173:             ParameterContext parameterContext, ExtensionContext extensionContext)
174:             throws ParameterResolutionException {
175:         Class<?> parameterType = parameterContext.getParameter().getType();
176:         if (parameterContext.isAnnotated(InjectClusterClient.class)
177:                 && ClusterClient.class.isAssignableFrom(parameterType)) {
178:             return true;
179:         }
180:         return internalMiniClusterExtension.supportsParameter(parameterContext, extensionContext);
181:     }
182: 
183:     @Override
184:     public Object resolveParameter(
185:             ParameterContext parameterContext, ExtensionContext extensionContext)
186:             throws ParameterResolutionException {
187:         Class<?> parameterType = parameterContext.getParameter().getType();
188:         if (parameterContext.isAnnotated(InjectClusterClient.class)) {
189:             if (parameterType.equals(RestClusterClient.class)) {
190:                 return extensionContext
191:                         .getStore(NAMESPACE)
192:                         .getOrComputeIfAbsent(
193:                                 CLUSTER_REST_CLIENT,
194:                                 k -> {
195:                                     try {
196:                                         return new CloseableParameter<>(
197:                                                 createRestClusterClient(
198:                                                         internalMiniClusterExtension));
199:                                     } catch (Exception e) {
200:                                         throw new ParameterResolutionException(
201:                                                 "Cannot create rest cluster client", e);
202:                                     }
203:                                 },
204:                                 CloseableParameter.class)
205:                         .get();
206:             }
207:             // Default to MiniClusterClient
208:             return extensionContext
209:                     .getStore(NAMESPACE)
210:                     .getOrComputeIfAbsent(
211:                             MINI_CLUSTER_CLIENT,
212:                             k -> {
213:                                 try {
214:                                     return new CloseableParameter<>(
215:                                             createMiniClusterClient(internalMiniClusterExtension));
216:                                 } catch (Exception e) {
217:                                     throw new ParameterResolutionException(
218:                                             "Cannot create mini cluster client", e);
219:                                 }
220:                             },
221:                             CloseableParameter.class)
222:                     .get();
223:         }
224:         return internalMiniClusterExtension.resolveParameter(parameterContext, extensionContext);
225:     }
226: 
227:     // Lifecycle implementation
228: 
229:     @Override
230:     public void beforeAll(ExtensionContext context) throws Exception {
231:         internalMiniClusterExtension =
232:                 new InternalMiniClusterExtension(miniClusterResourceConfigurationSupplier.get());
233:         internalMiniClusterExtension.beforeAll(context);
234:     }
235: 
236:     @Override
237:     public void beforeEach(ExtensionContext context) throws Exception {
238:         registerEnv(internalMiniClusterExtension);
239:     }
240: 
241:     @Override
242:     public void afterEach(ExtensionContext context) throws Exception {
243:         unregisterEnv(internalMiniClusterExtension);
244:     }
245: 
246:     @Override
247:     public void afterAll(ExtensionContext context) throws Exception {
248:         if (internalMiniClusterExtension != null) {
249:             internalMiniClusterExtension.afterAll(context);
250:         }
251:     }
252: 
253:     public TestEnvironment getTestEnvironment() {
254:         return this.streamTestEnvironment;
255:     }
256: 
257:     // Implementation
258: 
259:     private void registerEnv(InternalMiniClusterExtension internalMiniClusterExtension) {
260:         final Configuration configuration =
261:                 internalMiniClusterExtension.getMiniCluster().getConfiguration();
262: 
263:         final int defaultParallelism =
264:                 configuration
265:                         .getOptional(CoreOptions.DEFAULT_PARALLELISM)
266:                         .orElse(internalMiniClusterExtension.getNumberSlots());
267: 
268:         TestEnvironment batchTestExecutionEnvironment =
269:                 new TestEnvironment(
270:                         internalMiniClusterExtension.getMiniCluster(), defaultParallelism, false);
271:         batchTestExecutionEnvironment.setAsContext();
272:         this.streamTestEnvironment =
273:                 new TestEnvironment(
274:                         internalMiniClusterExtension.getMiniCluster(),
275:                         internalMiniClusterExtension.getNumberSlots(),
276:                         false);
277:         this.streamTestEnvironment.setAsContext();
278:         TestStreamEnvironment.setAsContext(
279:                 internalMiniClusterExtension.getMiniCluster(), defaultParallelism);
280:     }
281: 
282:     private void unregisterEnv(InternalMiniClusterExtension internalMiniClusterExtension) {
283:         TestStreamEnvironment.unsetAsContext();
284:         TestEnvironment.unsetAsContext();
285:     }
286: 
287:     private MiniClusterClient createMiniClusterClient(
288:             InternalMiniClusterExtension internalMiniClusterExtension) {
289:         return new MiniClusterClient(
290:                 internalMiniClusterExtension.getClientConfiguration(),
291:                 internalMiniClusterExtension.getMiniCluster());
292:     }
293: 
294:     private RestClusterClient<MiniClusterClient.MiniClusterId> createRestClusterClient(
295:             InternalMiniClusterExtension internalMiniClusterExtension) throws Exception {
296:         return new RestClusterClient<>(
297:                 internalMiniClusterExtension.getClientConfiguration(),
298:                 MiniClusterClient.MiniClusterId.INSTANCE);
299:     }
300: 
301:     // Utils
302: 
303:     public Configuration getClientConfiguration() {
304:         return internalMiniClusterExtension.getClientConfiguration();
305:     }
306: 
307:     public Integer getNumberSlots() {
308:         return internalMiniClusterExtension.getNumberSlots();
309:     }
310: 
311:     public boolean isRunning() {
312:         return internalMiniClusterExtension.getMiniCluster().isRunning();
313:     }
314: 
315:     private static class CloseableParameter<T extends AutoCloseable>
316:             implements ExtensionContext.Store.CloseableResource {
317:         private final T autoCloseable;
318: 
319:         CloseableParameter(T autoCloseable) {
320:             this.autoCloseable = autoCloseable;
321:         }
322: 
323:         public T get() {
324:             return autoCloseable;
325:         }
326: 
327:         @Override
328:         public void close() throws Throwable {
329:             this.autoCloseable.close();
330:         }
331:     }
332: }
