457:         final StreamExecutionEnvironment env =
458:                 StreamExecutionEnvironment.getExecutionEnvironment(jobConfig);
459: 
460:         env.enableCheckpointing(500);
461:         env.setStateBackend(backend);
462:         env.setParallelism(PARALLELISM);
463:         env.getCheckpointConfig()
464:                 .setExternalizedCheckpointRetention(
465:                         retainCheckpoints
466:                                 ? ExternalizedCheckpointRetention.RETAIN_ON_CANCELLATION
467:                                 : ExternalizedCheckpointRetention.DELETE_ON_CANCELLATION);
468:         RestartStrategyUtils.configureNoRestartStrategy(env);
