46: @Internal
47: public class FileSystemOutputFormat<T>
48:         implements OutputFormat<T>,
49:                 FinalizeOnMaster,
50:                 Serializable,
51:                 SupportsConcurrentExecutionAttempts {
52: 
53:     private static final long serialVersionUID = 1L;
54: 
