64:     private final OutputFormatFactory<T> formatFactory;
65:     private final OutputFileConfig outputFileConfig;
66:     private final ObjectIdentifier identifier;
67:     private final PartitionCommitPolicyFactory partitionCommitPolicyFactory;
68: 
