70:     private transient Configuration parameters;
71: 
72:     private FileSystemOutputFormat(
73:             FileSystemFactory fsFactory,
74:             TableMetaStoreFactory msFactory,
75:             boolean overwrite,
76:             boolean isToLocal,
77:             Path tmpPath,
78:             String[] partitionColumns,
79:             boolean dynamicGrouped,
80:             LinkedHashMap<String, String> staticPartitions,
81:             OutputFormatFactory<T> formatFactory,
82:             PartitionComputer<T> computer,
83:             OutputFileConfig outputFileConfig,
84:             ObjectIdentifier identifier,
85:             PartitionCommitPolicyFactory partitionCommitPolicyFactory) {
86:         this.fsFactory = fsFactory;
87:         this.msFactory = msFactory;
88:         this.overwrite = overwrite;
89:         this.isToLocal = isToLocal;
90:         this.tmpPath = tmpPath;
91:         this.partitionColumns = partitionColumns;
92:         this.dynamicGrouped = dynamicGrouped;
93:         this.staticPartitions = staticPartitions;
94:         this.formatFactory = formatFactory;
95:         this.computer = computer;
96:         this.outputFileConfig = outputFileConfig;
97:         this.identifier = identifier;
98:         this.partitionCommitPolicyFactory = partitionCommitPolicyFactory;
99:     }
