101:     @Override
102:     public void finalizeGlobal(FinalizationContext context) {
103:         try {
104:             List<PartitionCommitPolicy> policies = Collections.emptyList();
105:             if (partitionCommitPolicyFactory != null) {
106:                 policies =
107:                         partitionCommitPolicyFactory.createPolicyChain(
108:                                 Thread.currentThread().getContextClassLoader(),
109:                                 () -> {
110:                                     try {
111:                                         return fsFactory.create(tmpPath.toUri());
112:                                     } catch (IOException e) {
113:                                         throw new RuntimeException(e);
114:                                     }
115:                                 });
116:             }
117: 
118:             FileSystemCommitter committer =
119:                     new FileSystemCommitter(
120:                             fsFactory,
121:                             msFactory,
122:                             overwrite,
123:                             tmpPath,
124:                             partitionColumns.length,
125:                             isToLocal,
126:                             identifier,
127:                             staticPartitions,
128:                             policies);
129:             committer.commitPartitions(
130:                     (subtaskIndex, attemptNumber) -> {
131:                         try {
132:                             if (context.getFinishedAttempt(subtaskIndex) == attemptNumber) {
133:                                 return true;
134:                             }
135:                         } catch (IllegalArgumentException ignored) {
136:                             // maybe met a dir or file which does not belong to this job
137:                         }
138:                         return false;
139:                     });
140:         } catch (Exception e) {
141:             throw new TableException("Exception in finalizeGlobal", e);
142:         } finally {
143:             try {
144:                 fsFactory.create(tmpPath.toUri()).delete(tmpPath, true);
145:             } catch (IOException ignore) {
146:             }
147:         }
148:     }
