156:     public void open(InitializationContext context) throws IOException {
157:         try {
158:             PartitionTempFileManager fileManager =
159:                     new PartitionTempFileManager(
160:                             fsFactory,
161:                             tmpPath,
162:                             context.getTaskNumber(),
163:                             context.getAttemptNumber(),
164:                             outputFileConfig);
165:             PartitionWriter.Context<T> writerContext =
166:                     new PartitionWriter.Context<>(parameters, formatFactory);
167:             writer =
168:                     PartitionWriterFactory.<T>get(
169:                                     partitionColumns.length - staticPartitions.size() > 0,
170:                                     dynamicGrouped,
171:                                     staticPartitions)
172:                             .create(
173:                                     writerContext,
174:                                     fileManager,
175:                                     computer,
176:                                     new PartitionWriter.DefaultPartitionWriterListener());
177:         } catch (Exception e) {
178:             throw new TableException("Exception in open", e);
179:         }
180:     }
