321:     private void lazyInitializeForJob(
322:             Environment env, @SuppressWarnings("unused") String operatorIdentifier)
323:             throws IOException {
324: 
325:         if (isInitialized) {
326:             return;
327:         }
328: 
329:         this.jobId = env.getJobID();
330: 
331:         // initialize the paths where the local ForSt files should be stored
332:         if (localForStDirectories == null) {
333:             initializedDbBasePaths = new File[] {env.getTaskManagerInfo().getTmpWorkingDirectory()};
334:         } else {
335:             List<File> dirs = new ArrayList<>(localForStDirectories.length);
336:             StringBuilder errorMessage = new StringBuilder();
337: 
338:             for (File f : localForStDirectories) {
339:                 File testDir = new File(f, UUID.randomUUID().toString());
340:                 if (!testDir.mkdirs()) {
341:                     String msg =
342:                             "Local DB files directory '"
343:                                     + f
344:                                     + "' does not exist and cannot be created. ";
345:                     LOG.error(msg);
346:                     errorMessage.append(msg);
347:                 } else {
348:                     dirs.add(f);
349:                 }
350:                 //noinspection ResultOfMethodCallIgnored
351:                 testDir.delete();
352:             }
353: 
354:             if (dirs.isEmpty()) {
355:                 throw new IOException("No local storage directories available. " + errorMessage);
356:             } else {
357:                 initializedDbBasePaths = dirs.toArray(new File[0]);
358:             }
359:         }
360: 
361:         nextDirectory = new Random().nextInt(initializedDbBasePaths.length);
362: 
363:         isInitialized = true;
364:     }
365: 
366:     private File getNextStoragePath() {
367:         int ni = nextDirectory + 1;
368:         ni = ni >= initializedDbBasePaths.length ? 0 : ni;
369:         nextDirectory = ni;
370: 
371:         return initializedDbBasePaths[ni];
372:     }
