658:     /**
659:      * Sets the local directories in which the ForSt database puts some files (like metadata files).
660:      * These directories do not need to be persistent, they can be ephemeral, meaning that they are
661:      * lost on a machine failure, because state in ForSt is persisted in checkpoints.
662:      *
663:      * <p>If nothing is configured, these directories default to the TaskManager's local temporary
664:      * file directories.
665:      *
666:      * <p>Each distinct state will be stored in one path, but when the state backend creates
667:      * multiple states, they will store their files on different paths.
668:      *
669:      * <p>Passing {@code null} to this function restores the default behavior, where the configured
670:      * temp directories will be used.
671:      *
672:      * @param paths The paths across which the local ForSt database files will be spread.
673:      */
674:     public void setLocalDbStoragePaths(String... paths) {
675:         if (paths == null) {
676:             localForStDirectories = null;
677:         } else if (paths.length == 0) {
678:             throw new IllegalArgumentException("empty paths");
679:         } else {
680:             File[] pp = new File[paths.length];
681: 
682:             for (int i = 0; i < paths.length; i++) {
683:                 final String rawPath = paths[i];
684:                 final String path;
685: 
686:                 if (rawPath == null) {
687:                     throw new IllegalArgumentException("null path");
688:                 } else {
689:                     // we need this for backwards compatibility, to allow URIs like 'file:///'...
690:                     URI uri = null;
691:                     try {
692:                         uri = new Path(rawPath).toUri();
693:                     } catch (Exception e) {
694:                         // cannot parse as a path
695:                     }
696: 
697:                     if (uri != null && uri.getScheme() != null) {
698:                         if ("file".equalsIgnoreCase(uri.getScheme())) {
699:                             path = uri.getPath();
700:                         } else {
701:                             throw new IllegalArgumentException(
702:                                     "Path " + rawPath + " has a non-local scheme");
703:                         }
704:                     } else {
705:                         path = rawPath;
706:                     }
707:                 }
708: 
709:                 pp[i] = new File(path);
710:                 if (!pp[i].isAbsolute()) {
711:                     throw new IllegalArgumentException("Relative paths are not supported");
712:                 }
713:             }
714: 
715:             localForStDirectories = pp;
716:         }
717:     }
