322:     public void destroy() {
323:         synchronized (factoryLock) {
324:             isDestroyed = true;
325:         }
326: 
327:         synchronized (availableMemorySegments) {
328:             MemorySegment segment;
329:             while ((segment = availableMemorySegments.poll()) != null) {
330:                 segment.free();
331:             }
332:         }
333:     }
