455:     @Override
456:     public BufferPool createBufferPool(
457:             int numRequiredBuffers, int minUsedBuffers, int maxUsedBuffers) throws IOException {
458:         return internalCreateBufferPool(
459:                 numRequiredBuffers, minUsedBuffers, maxUsedBuffers, 0, Integer.MAX_VALUE, 0);
