462:     @Override
463:     public BufferPool createBufferPool(
464:             int numRequiredBuffers,
465:             int minUsedBuffers,
466:             int maxUsedBuffers,
467:             int numSubpartitions,
468:             int maxBuffersPerChannel,
469:             int maxOverdraftBuffersPerGate)
470:             throws IOException {
471:         return internalCreateBufferPool(
472:                 numRequiredBuffers,
473:                 minUsedBuffers,
474:                 maxUsedBuffers,
475:                 numSubpartitions,
476:                 maxBuffersPerChannel,
477:                 maxOverdraftBuffersPerGate);
