1252:     private Optional<String> getJobRestoreSavepointPath(
1253:             RestClusterClient<?> restClusterClient, String jobId) throws Exception {
1254:         CheckpointingStatistics checkpointingStatistics =
1255:                 sendJobRequest(
1256:                         restClusterClient,
1257:                         CheckpointingStatisticsHeaders.getInstance(),
1258:                         EmptyRequestBody.getInstance(),
1259:                         jobId);
1260: 
1261:         CheckpointingStatistics.RestoredCheckpointStatistics restoredCheckpointStatistics =
1262:                 checkpointingStatistics.getLatestCheckpoints().getRestoredCheckpointStatistics();
1263:         return restoredCheckpointStatistics != null
1264:                 ? Optional.ofNullable(restoredCheckpointStatistics.getExternalPath())
1265:                 : Optional.empty();
