193:     protected SubtaskAndFinishedState deserializeSubtaskIndexAndFinishedState(DataInputStream dis)
194:             throws IOException {
195:         int storedSubtaskIndex = dis.readInt();
196:         if (storedSubtaskIndex < 0) {
197:             return new SubtaskAndFinishedState(-storedSubtaskIndex - 1, true);
198:         } else {
199:             return new SubtaskAndFinishedState(storedSubtaskIndex, false);
200:         }
201:     }
