200:     private static final class LongCancelTimeMatcher<IN>
201:             implements JoinFunction<Tuple2<IN, IN>, Tuple2<IN, IN>, Tuple2<IN, IN>> {
202:         private static final long serialVersionUID = 1L;
203: 
204:         private static final int WAIT_TIME_PER_RECORD = 5 * 1000; // 5 sec.
205: 
206:         @Override
207:         public Tuple2<IN, IN> join(Tuple2<IN, IN> first, Tuple2<IN, IN> second) throws Exception {
208:             final long start = System.currentTimeMillis();
209:             long remaining = WAIT_TIME_PER_RECORD;
210:             do {
211:                 try {
212:                     Thread.sleep(remaining);
213:                 } catch (InterruptedException iex) {
214:                 }
215:             } while ((remaining = WAIT_TIME_PER_RECORD - System.currentTimeMillis() + start) > 0);
216:             return new Tuple2<>(first.f0, second.f0);
217:         }
218:     }
