222:         private static final long serialVersionUID = 1L;
223: 
224:         @Override
225:         public void open(OpenContext openContext) throws Exception {
226:             synchronized (this) {
227:                 wait();
228:             }
229:         }
230: 
231:         @Override
232:         public Tuple2<IN, IN> join(Tuple2<IN, IN> first, Tuple2<IN, IN> second) throws Exception {
233:             return new Tuple2<>(first.f0, second.f0);
234:         }
235:     }
