1157:         @Override
1158:         public void open(OpenContext openContext) throws Exception {
1159:             super.open(openContext);
1160:             if (getRuntimeContext().getTaskInfo().getIndexOfThisSubtask() == 0) {
1161:                 LATEST_CHECKPOINT_ID.set(0L);
1162:             }
1163:         }
1164: 
1165:         @Override
1166:         public void run(SourceContext<Tuple2<Integer, Long>> ctx) throws Exception {
1167:             // f0 => key
1168:             Tuple2<Integer, Long> record = new Tuple2<>(0, 1L);
1169: 
1170:             while (isRunning) {
1171:                 synchronized (ctx.getCheckpointLock()) {
1172:                     record.f0 = random.nextInt(numKeys);
