1141:     private static class TestKeyRangeSource
1142:             extends RichParallelSourceFunction<Tuple2<Integer, Long>>
1143:             implements CheckpointListener {
1144: 
1145:         private static final long serialVersionUID = -5744725196953582710L;
1146: 
1147:         private static final AtomicLong LATEST_CHECKPOINT_ID = new AtomicLong();
1148:         private final int numKeys;
1149:         private final ThreadLocalRandom random = ThreadLocalRandom.current();
1150:         private volatile boolean isRunning = true;
1151:         private int counter = 0;
1152: 
1153:         TestKeyRangeSource(int numKeys) {
1154:             this.numKeys = numKeys;
