1184:         @Override
1185:         public void cancel() {
1186:             isRunning = false;
1187:         }
1188: 
1189:         @Override
1190:         public void notifyCheckpointComplete(long checkpointId) throws Exception {
1191:             if (getRuntimeContext().getTaskInfo().getIndexOfThisSubtask() == 0) {
