190:         for (ExecutionJobVertex executionJobVertex :
191:                 getExecutionGraph().getVerticesTopologically()) {
192:             for (ExecutionVertex executionVertex : executionJobVertex.getTaskVertices()) {
193:                 if (executionVertex.getExecutionState() == ExecutionState.CREATED
194:                         || executionVertex.getExecutionState() == ExecutionState.SCHEDULED) {
195:                     deploySafely(executionVertex);
196:                 }
197:             }
