87:                 executionGraphHandler,
88:                 operatorCoordinatorHandler,
89:                 logger,
90:                 userCodeClassLoader,
91:                 failureCollection);
92:         this.context = context;
93:         Preconditions.checkState(
94:                 executionGraph.getState() == JobStatus.RUNNING, "Assuming running execution graph");
95: 
96:         this.sufficientResourcesController = new EnforceParallelismChangeRescalingController();
97:         this.desiredResourcesController =
