237:         int index = 0;
238:         /*
239:          * Here is a nested loop for collecting all values from a parquet page.
240:          * A column of array type can be considered as a list of lists, so the two loops are as below:
241:          * 1. The outer loop iterates on rows (index is a row index, so points to a row in the batch), e.g.:
242:          * [0, 2, 3]    <- index: 0
243:          * [NULL, 3, 4] <- index: 1
244:          *
245:          * 2. The inner loop iterates on values within a row (sets all data from parquet data page
246:          * for an element in ListColumnVector), so fetchNextValue returns values one-by-one:
247:          * 0, 2, 3, NULL, 3, 4
248:          *
249:          * As described below, the repetition level (repetitionLevel != 0)
250:          * can be used to decide when we'll start to read values for the next list.
251:          */
252:         while (!eof && index < total) {
253:             // add element to ListColumnVector one by one
254:             lcv.getOffsets()[index] = valueList.size();
255:             /*
256:              * Let's collect all values for a single list.
257:              * Repetition level = 0 means that a new list started there in the parquet page,
258:              * in that case, let's exit from the loop, and start to collect value for a new list.
259:              */
260:             do {
261:                 /*
262:                  * Definition level = 0 when a NULL value was returned instead of a list
263:                  * (this is not the same as a NULL value in of a list).
264:                  */
265:                 if (definitionLevel == 0) {
266:                     lcv.setNullAt(index);
267:                 }
268:                 valueList.add(
269:                         isCurrentPageDictionaryEncoded
270:                                 ? dictionaryDecodeValue(type, (Integer) heapLastValue)
